// ===== HIER ANPASSEN (der einzige Ort je Workflow) =====
const cfg = {
  supabaseUrl:  'https://DEIN-AGENCY-REF.supabase.co',
  auditorUrl:   'https://DEIN-N8N/webhook/agency-auditor',
  freigabeUrl:  'https://DEIN-N8N/webhook/agency-freigabe',
  kennzahlenUrl:'https://www.myimmoapp.de/api/intern/kennzahlen',
  mailAn:       'DEINE@MAIL.DE',
  mailVon:      'agency@myimmoapp.de',
  mailVonName:  'MyImmo Agency',
  githubRepo:   'jxnashap/myimmo-app',
};
// =======================================================
return [{ json: cfg }];

const k = $('MyImmo-Kennzahlen').first().json;
const b = $input.first().json;

// Nicht gemessen ist NICHT null-gleich-Ergebnis. Wer beides gleich darstellt,
// hält eine Lücke für einen Wert.
const z = (w, einheit = '') => (w === null || w === undefined) ? 'nicht gemessen' : w + einheit;

const zeilen = [
  ['1 · Besucher (7 Tage)',        z(k.besucher7t)],
  ['2 · Neue externe Konten (7 T)', z(k.neueKonten7t)],
  ['3 · Aktivierung (Konto→Objekt)', z(k.aktivierungsquote, ' %') + '  (' + k.mitObjekt + ' von ' + k.externeKonten + ')'],
  ['4 · Rückkehrer (2. Tag)',      z(k.rueckkehrerquote, ' %') + '  (' + k.rueckkehrer + ' von ' + k.externeKonten + ')'],
  ['5 · Zahlende Kunden',          z(k.zahlendeKunden)],
  ['    Ausgaben Monat',           z(b.ausgaben_monat_usd, ' USD') + ' von ' + z(b.deckel_usd, ' USD')],
];

// Abbruchkriterien aus docs/zukunft/AI-AGENCY-OS.md 4.4 — sie stehen hier im
// Code, damit sie jede Woche geprüft werden und nicht nur im Dokument stehen.
const warnungen = [];
if (k.aktivierungsquote !== null && k.aktivierungsquote < 40)
  warnungen.push('Aktivierung unter 40 % — Onboarding ist das Problem, keine neuen Funktionen.');
if (k.rueckkehrerquote !== null && k.rueckkehrerquote < 25)
  warnungen.push('Rückkehrer unter 25 % — das Produkt löst kein wiederkehrendes Problem. Positionierung prüfen.');
if (b.budget_ok === false)
  warnungen.push('Monatsdeckel erreicht — die Agency ist gesperrt, bis der Monat wechselt oder der Deckel steigt.');
if (k.besucher7t === null)
  warnungen.push('Zahl 1 fehlt weiterhin: @vercel/analytics ist nicht installiert.');

const breite = Math.max(...zeilen.map(r => r[0].length));
const text = zeilen.map(r => r[0].padEnd(breite + 2) + r[1]).join('\n');

const html = '<div style="font-family:system-ui,sans-serif;max-width:680px">'
  + '<h2 style="font-weight:600">Wochenbericht MyImmo</h2>'
  + '<pre style="white-space:pre-wrap;font:14px ui-monospace,monospace">' + text + '</pre>'
  + (warnungen.length
      ? '<div style="border-left:3px solid #D4A847;padding:8px 14px;background:#fbf7ec">'
        + warnungen.map(w => '<p style="margin:6px 0">' + w + '</p>').join('') + '</div>'
      : '<p style="color:#666">Keine Schwelle verletzt.</p>')
  + '<p style="color:#666;font-size:12px">Stand ' + (k.stand ?? '') + '</p></div>';

return [{ json: { kennzahlen: { ...k, budget: b }, text, html, warnungen,
  betreff: '[Agency] Wochenbericht — ' + z(k.zahlendeKunden) + ' zahlend, '
    + z(k.rueckkehrerquote, ' %') + ' Rückkehrer' } }];
